c3RzL3N0YXRpY190ZXN0LnB5UEsBAhQDFAAAAAgAwLMyXa5tKy+8BAAAQQsAADwAAAAAAAAAAAAAALaB6hIDAEpOU19IQV9XaW5k
b3dzX01hbmFnZXJfdjUuNS4wL3Rlc3RzL3Y1X2NvbXBhdGliaWxpdHlfdGVzdC5weVBLBQYAAAAAggCCADI+AAAAGAMAAAA=
'@
$ManagerRoot = Join-Path $JnsRoot "WindowsManager"
$Current = Join-Path $ManagerRoot "current"
$BackupRoot = Join-Path $JnsRoot "backups"
$LogRoot = Join-Path $JnsRoot "logs"
$VersionFile = Join-Path $ManagerRoot "CURRENT_VERSION.txt"

function Section([string]$x) { Write-Host "`n===============================================================================" -ForegroundColor DarkCyan; Write-Host " $x" -ForegroundColor Cyan; Write-Host "===============================================================================" -ForegroundColor DarkCyan }
function Pass([string]$x) { Write-Host "[PASS] $x" -ForegroundColor Green }
function Info([string]$x) { Write-Host "[INFO] $x" -ForegroundColor Cyan }
function Warn([string]$x) { Write-Host "[WARN] $x" -ForegroundColor Yellow }

if (-not (Test-Path -LiteralPath $Current)) { throw "Existing JNS Windows Manager not found at $Current. Run Stage 2 first." }
New-Item -ItemType Directory -Force -Path $BackupRoot,$LogRoot | Out-Null
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$log = Join-Path $LogRoot "JNS_Windows_Manager_v5.5.0_Update_$stamp.log"
Start-Transcript -Path $log -Force | Out-Null
$temp = Join-Path ([IO.Path]::GetTempPath()) ("JNS-v5.5-update-" + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Force -Path $temp | Out-Null
try {
    Section "JNS WINDOWS MANAGER v5.5.0 — MANAGEMENT PC ENROLLMENT UPDATE"
    Info "Existing manager: $Current"
    Info "DPAPI vault remains in %APPDATA%\JNS\WindowsManager and is not copied or replaced."

    Section "1. VERIFY EMBEDDED RELEASE"
    $payload = Join-Path $temp "JNS_HA_Windows_Manager_v5.5.0_FULL_DISTRIBUTION.zip"
    $clean = ($PayloadBase64 -replace "\s", "")
    [IO.File]::WriteAllBytes($payload, [Convert]::FromBase64String($clean))
    $actual = (Get-FileHash -LiteralPath $payload -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($actual -ne $ExpectedPayloadSha256) { throw "Embedded release SHA-256 mismatch. Expected $ExpectedPayloadSha256, got $actual" }
    Pass "Embedded v5.5.0 release SHA-256 verified."

    Section "2. BACK UP CURRENT MANAGER SOURCE"
    $backup = Join-Path $BackupRoot "WindowsManager-pre-v5.5.0-$stamp"
    New-Item -ItemType Directory -Force -Path $backup | Out-Null
    Get-ChildItem -LiteralPath $Current -Force | Where-Object { $_.Name -notin @('.venv','packages','__pycache__','.pytest_cache') } | ForEach-Object {
        Copy-Item -LiteralPath $_.FullName -Destination $backup -Recurse -Force
    }
    Pass "Rollback source copy created: $backup"

    Section "3. INSTALL v5.5.0 IN PLACE"
    $extract = Join-Path $temp "extract"
    Expand-Archive -LiteralPath $payload -DestinationPath $extract -Force
    $source = Join-Path $extract "JNS_HA_Windows_Manager_v5.5.0"
    if (-not (Test-Path -LiteralPath (Join-Path $source 'JNS_HA_Windows_Manager.pyw'))) { throw "v5.5.0 payload structure is invalid." }
    Get-ChildItem -LiteralPath $source -Force | Where-Object { $_.Name -notin @('packages','.venv','__pycache__','.pytest_cache') } | ForEach-Object {
        Copy-Item -LiteralPath $_.FullName -Destination $Current -Recurse -Force
    }
    $Version | Set-Content -LiteralPath $VersionFile -Encoding ASCII
    Pass "Manager source updated to v5.5.0; existing package library retained."

    Section "4. VERIFY PYTHON ENVIRONMENT"
    $python = Join-Path $Current ".venv\Scripts\python.exe"
    if (-not (Test-Path -LiteralPath $python)) {
        $stage1 = "C:\projects\.venv\jns-management\Scripts\python.exe"
        if (-not (Test-Path -LiteralPath $stage1)) { throw "No JNS Python environment found. Re-run Stage 1." }
        & $stage1 -m venv (Join-Path $Current '.venv')
        if ($LASTEXITCODE -ne 0) { throw "Could not create manager virtual environment." }
    }
    & $python -m pip install --disable-pip-version-check -r (Join-Path $Current 'requirements.txt')
    if ($LASTEXITCODE -ne 0) { throw "Python dependency update failed." }
    Pass "Python dependencies are ready."
    Section "5. v5.5 REGRESSION CHECKS"
    foreach ($test in @('static_test.py','management_pc_enrollment_test.py','package_crypto_test.py','v5_compatibility_test.py')) {
        & $python (Join-Path $Current ("tests\" + $test))
        if ($LASTEXITCODE -ne 0) { throw "Regression check failed: $test" }
    }
    Pass "v5.5 manager regression checks passed."

    Section "UPDATE COMPLETE"
    Write-Host "Windows Manager v5.5.0 is installed." -ForegroundColor Green
    Write-Host ""
    Write-Host "Next: update Home Assistant JNS Deployment Platform to v5.5.0 through an already-authorized path." -ForegroundColor Cyan
    Write-Host "Then in Home Assistant create a one-time management-PC enrollment code and click ENROLL THIS PC." -ForegroundColor Cyan
    Write-Host "Do not revoke the old PC until COMMISSION THIS PC passes the signed deployment + rollback test." -ForegroundColor Yellow
    Write-Host "Log: $log"

    if (-not $NoLaunch) {
        $launcher = Join-Path $JnsRoot 'Launch-JNS-Management-Console.ps1'
        if (Test-Path -LiteralPath $launcher) {
            & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $launcher
        } else {
            & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $Current 'run_manager.ps1')
        }
    }
} catch {
    Write-Host "`n[FAIL] JNS v5.5.0 update failed: $($_.Exception.Message)" -ForegroundColor Red
    Write-Host "Existing DPAPI secrets were not deliberately changed by this updater." -ForegroundColor Yellow
    Write-Host "Rollback source copy (if created): $backup" -ForegroundColor Yellow
    exit 1
} finally {
    try { Stop-Transcript | Out-Null } catch {}
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
}
